/// @default Path(Engine, "EngineResources/DefaultTexture")
/// @sort 32
uniform Texture2D Source;
// A texture default is an asset reference, carried unresolved as `/// @default`.
/// @name M_LpTextureDefault
export void M_LpTextureDefault(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    Color = UE.Expression(Class = "TextureSample", TextureObject = Source, Coordinates = UE.TexCoord(Index = 0)).rgb;
    Base.EmissiveColor = Color;
}
